<script setup> import { onMounted, ref } from'vue' import { CheckCircle2, XCircle, Loader2, ArrowRight, AlertTriangle, FileCheck2 } from'lucide-vue-next' import { useRoute, useRouter } from'vue-router' import api from'../services/api' const route = useRoute() const router = useRouter() const data = ref(null) const error = ref('') const loading = ref(true) const submitting = ref(false) const choiceMade = ref(false) const choiceResult = ref(null) // { continuer: boolean, detail: string, participationTestId: uuid } const showModalConfirm = ref(false) const pendingChoice = ref(null) // true (Oui) ou false (Non) const loadData = async () => { try { const res = await api.get(`evaluations/confirmation-presence/${route.params.token}/`) data.value = res.data if (data.value.confirmee || data.value.statutCandidature ==='TERMINEE') { choiceMade.value = true } } catch (err) { error.value = err.response?.data?.detail ||'Ce lien de confirmation est invalide ou expiré.' } finally { loading.value = false } } const openConfirmModal = (continuerChoice) => { pendingChoice.value = continuerChoice showModalConfirm.value = true } const submitChoice = async () => { if (pendingChoice.value === null) return submitting.value = true showModalConfirm.value = false try { const res = await api.post(`evaluations/confirmation-presence/${route.params.token}/`, { continuer: pendingChoice.value }) choiceMade.value = true choiceResult.value = res.data } catch (err) { error.value = err.response?.data?.detail ||'Erreur lors de la prise en compte de votre choix.' } finally { submitting.value = false } } onMounted(loadData) </script> <template> <main class="min-h-screen bg-[#01313E] text-white flex items-center justify-center p-6"> <div class="w-full max-w-lg bg-[#01313E] rounded-3xl p-8 border border-[#01313E] space-y-6"> <!-- CHARGEMENT --> <div v-if="loading"class="py-12 text-center space-y-3"> <Loader2 class="mx-auto h-10 w-10 animate-spin text-[#01313E]"/> <p class="text-sm text-[#01313E]/60">Chargement de votre fiche de confirmation...</p> </div> <!-- ERREUR OU LINK INVALIDE --> <div v-else-if="error"class="text-center space-y-4 py-6"> <div class="w-14 h-14 bg-[#E30046]/10 text-[#E30046] rounded-2xl flex items-center justify-center mx-auto"> <XCircle class="w-8 h-8"/> </div> <h1 class="text-xl font-bold text-white">Lien indisponible</h1> <p class="text-sm text-[#01313E]/60 max-w-xs mx-auto">{{ error }}</p> </div> <!-- CHOIX DÉJÀ EFFECTUÉ OU RÉPONSE SOUMISE --> <div v-else-if="choiceMade"class="text-center space-y-6 py-4"> <template v-if="choiceResult ? choiceResult.continuer : data.statutCandidature !=='TERMINEE'"> <div class="w-16 h-16 bg-[#01313E]/20 text-[#01313E] rounded-2xl flex items-center justify-center mx-auto"> <CheckCircle2 class="w-10 h-10"/> </div> <div> <h1 class="text-2xl font-extrabold text-white mb-2">Candidature Maintenue !</h1> <p class="text-sm text-white"> Merci {{ data.nom }}. Votre souhait de continuer le parcours de sélection est bien pris en compte. </p> </div> <div class="p-5 bg-blue-950/50 border border-[#01313E]/60 rounded-2xl text-left space-y-2"> <div class="flex items-center gap-2 text-[#01313E] font-bold text-sm"> <FileCheck2 class="w-5 h-5"/> <span>Prochaine étape : Étape 3 (Test QCM)</span> </div> <p class="text-xs text-white"> Votre confirmation a bien été enregistrée. Lorsque l'Équipe Pédagogique aura publié le test QCM pour votre cohorte, vous recevrez une notification et le test sera disponible sur votre espace candidat. </p> </div> <div class="pt-2"> <button @click="router.push('/login')" class="w-full py-3 bg-[#01313E] hover:bg-[#01313E] text-white font-bold text-sm rounded-xl transition" > Accéder à mon espace candidat </button> </div> </template> <template v-else> <div class="w-16 h-16 bg-[#01313E] text-[#01313E]/60 rounded-2xl flex items-center justify-center mx-auto"> <XCircle class="w-10 h-10"/> </div> <div> <h1 class="text-xl font-bold text-white mb-2">Parcours de Candidature Clôturé</h1> <p class="text-sm text-[#01313E]/60"> Votre décision d'arrêter votre procédure de candidature a bien été enregistrée. Nous vous remercions pour votre intérêt. </p> </div> </template> </div> <!-- FORMULAIRE DE CHOIX : SOUHAITEZ-VOUS CONTINUER ? --> <div v-else class="space-y-6"> <div class="text-center space-y-2"> <span class="px-3 py-1 bg-[#01313E]/10 text-[#01313E] text-xs font-semibold rounded-full border border-[#01313E]/20"> Étape 2 : Réunion d'information </span> <h1 class="text-2xl font-bold text-white pt-2">Confirmation de Parcours</h1> <p class="text-sm text-[#01313E]/60"> Bonjour <strong class="text-white">{{ data.nom }}</strong>, votre présence à la Réunion d'information a été validée. </p> </div> <div class="bg-[#01313E]/40 p-5 rounded-2xl border border-[#01313E] text-center space-y-2"> <p class="text-sm font-bold text-white"> Souhaitez-vous continuer votre procédure de candidature ? </p> <p class="text-xs text-[#01313E]/60"> En répondant oui, vous accéderez directement à l'Étape 3 (Test QCM). </p> </div> <!-- BOUTONS OUI / NON --> <div class="grid grid-cols-1 sm:grid-cols-2 gap-4"> <button @click="openConfirmModal(true)" class="py-3.5 px-4 bg-[#01313E] hover:bg-[#01313E] text-white font-bold rounded-2xl transition flex items-center justify-center gap-2" > <CheckCircle2 class="w-5 h-5"/> <span>Oui, je continue</span> </button> <button @click="openConfirmModal(false)" class="py-3.5 px-4 bg-[#E30046]/20 hover:bg-[#E30046]/30 text-[#E30046] border border-[#E30046]/30 font-semibold rounded-2xl transition flex items-center justify-center gap-2" > <XCircle class="w-5 h-5"/> <span>Non, j'arrête</span> </button> </div> </div> </div> <!-- MODAL DE CONFIRMATION DU CHOIX --> <div v-if="showModalConfirm"class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80"> <div class="bg-[#01313E] rounded-3xl max-w-md w-full p-6 border border-[#01313E] space-y-5 text-center"> <div class="w-12 h-12 bg-[#01313E]/20 text-[#01313E] rounded-2xl flex items-center justify-center mx-auto"> <AlertTriangle class="w-6 h-6"/> </div> <div> <h3 class="text-lg font-bold text-white">Confirmation de votre décision</h3> <p class="text-sm text-white mt-2"> Êtes-vous sûr(e) de vouloir <strong :class="pendingChoice ?'text-[#01313E]' :'text-[#E30046]'"> {{ pendingChoice ?'continuer votre candidature' :'arrêter votre candidature' }} </strong> ? </p> <p v-if="!pendingChoice"class="text-xs text-[#E30046]/80 mt-1"> Attention: Cette décision est définitive et arrêtera votre processus de sélection. </p> </div> <div class="flex items-center justify-center gap-3 pt-2"> <button @click="showModalConfirm = false" class="px-5 py-2.5 text-sm font-medium text-white hover:bg-[#01313E] rounded-xl transition" > Annuler </button> <button @click="submitChoice" :disabled="submitting" class="px-6 py-2.5 text-sm font-bold text-white rounded-xl transition" :class="pendingChoice ?'bg-[#01313E] hover:bg-[#01313E]' :'bg-[#E30046] hover:bg-[#E30046]'" > <Loader2 v-if="submitting"class="w-4 h-4 animate-spin inline mr-1"/> <span>Confirmer mon choix</span> </button> </div> </div> </div> </main> </template> 